"""Kerr QNM frequencies generated by TorchWave's own equation solver.

No external QNM tables, waveform outputs or external QNM solver supply the
coefficients. Reproduce with scripts/generate_kerr_qnm_independent.py.
The generator and numerical data are original TorchWave work under MIT.
See docs/reviews/2026-09-12-clean-room/pass-7-independent-qnm.md.
"""

from functools import lru_cache

import torch

DEGREE = 5
SPIN_MIN = 0.0
SPIN_MAX = 0.99999

# BEGIN GENERATED INDEPENDENT DATA
_SPLINES = {}
# END GENERATED INDEPENDENT DATA

SUPPORTED_MODES = tuple(_SPLINES)


@lru_cache(maxsize=64)
def _spline_tensors(mode, device):
    knots, coefficients = _SPLINES[mode]
    # Cached constants must be ordinary tensors even if their first caller
    # runs in inference mode and a later caller requests spin derivatives.
    with torch.inference_mode(False):
        return (torch.tensor(knots, dtype=torch.float64, device=device),
                torch.tensor(coefficients, dtype=torch.float64, device=device))


def dimensionless_qnm(l, m, n, final_spin):
    """Return positive ``(Re(M omega), -Im(M omega))`` for a labelled mode.

    Tensor inputs preserve shape, floating dtype, device and spin gradients.
    Scalars use float64. Spins must be finite and in [0, 0.99999]; a negative
    m selects the counterrotating branch. Interpolation uses float64 working
    arithmetic. The supported modes and finite-set accuracy are documented
    alongside the generator's residual and resolution checks.
    """
    mode = (l, m, n)
    if mode not in _SPLINES:
        raise ValueError(f"Unsupported independently generated QNM mode {mode}")
    spin = (final_spin if isinstance(final_spin, torch.Tensor)
            else torch.as_tensor(final_spin, dtype=torch.float64))
    if not spin.is_floating_point():
        raise TypeError("final_spin must have a floating dtype")
    if bool(torch.any(~torch.isfinite(spin) | (spin < SPIN_MIN) | (spin > SPIN_MAX))):
        raise ValueError(f"QNM spin domain is [{SPIN_MIN}, {SPIN_MAX}]")
    x = -torch.log1p(-spin.to(torch.float64))
    knots, coefficients = _spline_tensors(mode, spin.device)
    interval = (torch.searchsorted(knots, x.contiguous(), right=True) - 1).clamp(
        min=DEGREE, max=len(coefficients) - 1)
    values = [coefficients[interval - DEGREE + j] for j in range(DEGREE + 1)]
    for r in range(1, DEGREE + 1):
        for j in range(DEGREE, r - 1, -1):
            left = knots[interval - DEGREE + j]
            right = knots[interval + 1 + j - r]
            alpha = ((x - left) / (right - left)).unsqueeze(-1)
            values[j] = (1.0 - alpha) * values[j - 1] + alpha * values[j]
    result = values[DEGREE].to(spin.dtype)
    return result[..., 0], -result[..., 1]


def signed_qnm_220(spin):
    """Positive-frequency 220 root across signed spin, without clamping."""
    positive = dimensionless_qnm(2, 2, 0, spin.clamp_min(0))
    negative = dimensionless_qnm(2, -2, 0, (-spin).clamp_min(0))
    return tuple(torch.where(spin >= 0, p, n) for p, n in zip(positive, negative))
